import os,subprocess,json,hashlib
from pathlib import Path
R=Path('/storage/qa614');R.mkdir(mode=0o700)
(R/'fake-rclone').write_text('#!/usr/bin/python3\nimport os,sys,json,time,http.server\nfrom pathlib import Path\nROOT=Path(\'/storage/qa614\')\nif len(sys.argv)<2 or sys.argv[1]!=\'authorize\':os.execv(str(ROOT/\'rclone-original\'),sys.argv)\nPAGE=\'\'\'<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="font:20px sans-serif;background:#fff;color:#123"><h1>Browser exit test</h1><p>Synthetic local page. No account is used.</p><input id="field" type="text" placeholder="Test keyboard"><div id="consent" style="border:2px solid #234;padding:10px">Consent-style overlay <button onclick="document.getElementById(\'consent\').remove()">Dismiss</button></div><p id="events">Waiting for input</p><script>\nfunction log(kind,e){let v={kind:kind,key:e?.key||\'\',trusted:e?.isTrusted||false,active:document.activeElement?.id||\'\',length:document.querySelector(\'#field\').value.length,at:Date.now()};document.querySelector(\'#events\').textContent=JSON.stringify(v);fetch(\'/event\',{method:\'POST\',body:JSON.stringify(v),keepalive:true}).catch(()=>{});}\nwindow.addEventListener(\'keydown\',e=>log(\'keydown-capture\',e),true);window.addEventListener(\'keydown\',e=>log(\'keydown-bubble\',e));window.addEventListener(\'focus\',e=>log(\'focus\',e));window.addEventListener(\'blur\',e=>log(\'blur\',e));document.querySelector(\'#field\').addEventListener(\'input\',e=>log(\'input\',e));window.addEventListener(\'load\',()=>{document.querySelector(\'#field\').focus();log(\'loaded\')});\n</script></body></html>\'\'\'.encode()\nclass H(http.server.BaseHTTPRequestHandler):\n def log_message(self,*a):pass\n def do_GET(self):\n  if self.path.startswith(\'/auth\'):\n   self.send_response(302);self.send_header(\'Location\',\'http://127.0.0.1:53682/page\');self.end_headers();return\n  self.send_response(200);self.send_header(\'Content-Type\',\'text/html\');self.send_header(\'Content-Length\',str(len(PAGE)));self.end_headers();self.wfile.write(PAGE)\n def do_HEAD(self):self.do_GET()\n def do_POST(self):\n  n=int(self.headers.get(\'Content-Length\',\'0\'));assert 0<=n<=4096\n  row=json.loads(self.rfile.read(n));row[\'host_monotonic\']=time.monotonic()\n  with (ROOT/\'page-events.jsonl\').open(\'a\') as f:f.write(json.dumps(row)+\'\\n\')\n  self.send_response(204);self.end_headers()\nserver=http.server.HTTPServer((\'127.0.0.1\',53682),H)\nprint(\'http://127.0.0.1:53682/auth?state=synthetic-qa614\',flush=True)\nserver.serve_forever()\n')
(R/'observer.py').write_text("import os,json,time,signal,struct,selectors\nfrom pathlib import Path\nR=Path('/storage/qa614');sel=selectors.DefaultSelector();opened={};deadlines={};handled=set();guards=[];start=time.monotonic();nxt=0\n\ndef record(name,value):\n with (R/name).open('a') as f:f.write(json.dumps(value)+'\\n')\ndef processes():\n rows=[]\n for p in Path('/proc').iterdir():\n  if not p.name.isdigit():continue\n  try:\n   argv=(p/'cmdline').read_bytes().replace(b'\\0',b' ').decode(errors='replace');stat=(p/'stat').read_text().rsplit(')',1)[1].split()\n   if any(x in argv for x in ['cloud-signin-window','WebKit','cloud_oauth','emulationstation']):rows.append({'pid':int(p.name),'start':int(stat[19]),'argv':argv,'state':stat[0]})\n  except (FileNotFoundError,ProcessLookupError):pass\n return rows\ntry:\n while time.monotonic()-start<1800 and not (R/'stop').exists():\n  now=time.monotonic()\n  for p in Path('/dev/input').glob('event*'):\n   if str(p) in opened:continue\n   fd=os.open(p,os.O_RDONLY|os.O_NONBLOCK);opened[str(p)]=fd;sel.register(fd,selectors.EVENT_READ,str(p));record('input.jsonl',{'at':now,'opened':str(p)})\n  for key,_ in sel.select(.1):\n   try:data=os.read(key.fd,struct.calcsize('llHHi')*128)\n   except OSError:sel.unregister(key.fd);os.close(key.fd);continue\n   for sec,usec,typ,code,val in struct.iter_unpack('llHHi',data):\n    if typ==1:record('input.jsonl',{'at':now,'device':key.data,'type':typ,'code':code,'value':val})\n  if now>=nxt:\n   rows=processes();record('samples.jsonl',{'at':now,'processes':rows,'meminfo':Path('/proc/meminfo').read_text(),'pressure':Path('/proc/pressure/memory').read_text()});nxt=now+1\n   for row in rows:\n    if not row['argv'].startswith('/usr/bin/cloud-signin-window '):continue\n    identity=(row['pid'],row['start']);deadlines.setdefault(identity,now+90)\n    if now>=deadlines[identity] and identity not in handled:\n     fd=os.pidfd_open(row['pid']);current=next((r for r in processes() if (r['pid'],r['start'])==identity),None)\n     if current:signal.pidfd_send_signal(fd,signal.SIGTERM);guards.append({'at':now,'identity':row,'reason':'90s emergency deadline'});record('guard.jsonl',guards[-1])\n     os.close(fd);handled.add(identity)\nfinally:\n for key in list(sel.get_map().values()):sel.unregister(key.fd);os.close(key.fd)\n (R/'observer-result.json').write_text(json.dumps({'rc':int(bool(guards)),'guards':guards,'elapsed':time.monotonic()-start,'stopped':(R/'stop').exists()})+'\\n')\nraise SystemExit(int(bool(guards)))\n")
(R/'fake-rclone').chmod(0o755)
subprocess.run(['cp','/usr/bin/rclone',str(R/'rclone-original')],check=True)
subprocess.run(['mount','--bind',str(R/'fake-rclone'),'/usr/bin/rclone'],check=True)
subprocess.run(['systemctl','set-environment','CLOUD_SIGNIN_DEBUG=1'],check=True)
subprocess.run(['systemctl','restart','essway'],check=True)
subprocess.run(['systemd-run','--unit=qa614-observer','--property=RuntimeMaxSec=1800','/usr/bin/python3','-I','-B',str(R/'observer.py')],check=True)
print('FIXTURE_READY')
